// find_free_time on the device against the server's (OpenSpec change
// assistant-time-blocks, task 1.2): freeTimeRead.vectors.json is generated by
// `go test ./internal/assistant -run Device -update` from the registry's answers
// over the same rows; here the same calls run against this device's rows.
import 'fake-indexeddb/auto'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { AGENT_EXCLUSIONS_KEY } from '../agentAccess'
import { db, setMeta, useDatabase } from '../db'
import { setCurrentUserId } from '../sharing'
import { ArgError } from './args'
import { loadSnapshot } from './data'
import { findFreeTime } from './readFreeTime'
import vectors from './freeTimeRead.vectors.json'

// The calendar's events are fetched first, like a calendar view; this server has none to give.
const fetchMock = vi.fn(async () => new Response('{}', { status: 404 }))
afterEach(() => { vi.unstubAllGlobals() })

let n = 0
beforeEach(async () => {
  vi.stubGlobal('fetch', fetchMock)
  useDatabase(`device-free-time-${Date.now()}-${n++}`)
  await setCurrentUserId(vectors.user)
  const rows = vectors.rows as Record<string, Record<string, unknown>[]>
  const put = (r: Record<string, unknown>[]) => r.map((x) => ({ ...x, _clock: {} })) as never
  await db.projects.bulkPut(put(rows.project))
  await db.tasks.bulkPut(put(rows.task))
  await db.frames.bulkPut(put(rows.frame))
  await db.slots.bulkPut(put(rows.slot))
  await setMeta(AGENT_EXCLUSIONS_KEY, vectors.kept_away)
})

describe('find_free_time vectors', () => {
  for (const c of vectors.cases as { name: string; args: Record<string, unknown>; error?: string; result?: unknown }[]) {
    it(c.name, async () => {
      let got: unknown
      let code = ''
      try {
        got = await findFreeTime(await loadSnapshot(), c.args, vectors.now)
      } catch (err) {
        if (!(err instanceof ArgError)) throw err
        code = 'invalid_arguments'
      }
      expect(code).toBe(c.error ?? '')
      if (!c.error) expect(JSON.parse(JSON.stringify(got))).toEqual(c.result)
    })
  }

  it('reads the working day from the calendar settings when the call names none', async () => {
    await setMeta('calendar.grid', { startHour: 9, endHour: 17, dayLength: 480 })
    const out = await findFreeTime(await loadSnapshot(), { from: '2026-10-14' }, vectors.now)
    expect(out.working_day).toEqual({ start: '09:00', end: '17:00' })
    expect(out.days[0].free).toEqual([{ start: '09:00', end: '17:00', minutes: 480 }])
  })
})
